'use strict';
const R=RaceRules,$=id=>document.getElementById(id),board=$('board'),NS='http://www.w3.org/2000/svg';
const OR=36,S=24,xy=p=>({x:OR+p.x*S,y:OR+p.y*S}),fmt=n=>Number(n.toFixed(3));
let track=R.makeTrack(R.presets.bay),state=null,history=[],practice=false,preview=null,editing=false,draft=[],draftTrack=null,drawing=false,lastDrag=null,custom=null,toastTimer;
function el(tag,attrs={},text){const n=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n;}
function pointStr(points){return points.map(p=>{p=xy(p);return `${fmt(p.x)},${fmt(p.y)}`;}).join(' ');}
function line(a,b,attrs={}){const p=xy(a),q=xy(b);return el('line',{x1:p.x,y1:p.y,x2:q.x,y2:q.y,...attrs});}
function textAt(p,text,attrs={}){p=xy(p);return el('text',{x:p.x,y:p.y,'font-size':13,fill:'#75869e',...attrs},text);}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3200);}
function stored(key,value){try{if(value!==undefined)localStorage.setItem(key,JSON.stringify(value));else return JSON.parse(localStorage.getItem(key));}catch{}return null;}
function recordKey(){return 'paper-racer-v2-circle:'+JSON.stringify([track.points,track.width]);}
function reset(){state=null;history=[];practice=false;preview=null;render();}
function chooseStart(p){if(editing)return;state={position:{...p},velocity:R.P(0,0),status:'running',impact:{...p}};history=[structuredClone(state)];practice=false;preview=null;render();}
function move(ax,ay){if(editing||!state||state.status!=='running')return;state=R.evaluate(track,state,ax,ay);history.push(structuredClone(state));preview=null;if(state.status==='finished'&&!practice){const best=stored(recordKey());const turns=history.length-1;if(!Number.isInteger(best)||turns<best)stored(recordKey(),turns);}render();}
function undo(){if(editing||history.length<2)return;history.pop();state=structuredClone(history.at(-1));practice=true;preview=null;render();}
function actionPoint(p,r,attrs,onClick,label){const q=xy(p),c=el('circle',{cx:q.x,cy:q.y,r,role:'button',tabindex:0,'aria-label':label,...attrs});c.addEventListener('click',e=>{e.stopPropagation();onClick();});c.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onClick();}});return c;}
function drawTrack(t){board.append(el('polygon',{points:pointStr(t.polygon),fill:'#f1f5fc'}));for(const side of [t.polygon.slice(0,t.path.length),t.polygon.slice(t.path.length).reverse()])board.append(el('polyline',{points:pointStr(side),fill:'none',stroke:'#2c405b','stroke-width':3,'stroke-linejoin':'round','stroke-linecap':'round'}));for(const [gate,color,label]of [[t.start,'#15886e','START'],[t.finish,'#8051c9','FINISH']]){board.append(line(...gate,{stroke:color,'stroke-width':5}));const mid={x:(gate[0].x+gate[1].x)/2,y:(gate[0].y+gate[1].y)/2};board.append(textAt({x:mid.x,y:mid.y+1.1},label,{fill:color,'font-size':13,'font-weight':700,'text-anchor':'middle','letter-spacing':2}));}}
function renderBoard(){board.replaceChildren();const defs=el('defs'),pattern=el('pattern',{id:'grid',width:S,height:S,patternUnits:'userSpaceOnUse',x:OR,y:OR});pattern.append(el('path',{d:`M ${S} 0 L 0 0 0 ${S}`,fill:'none',stroke:'#dce6f3','stroke-width':1}));defs.append(pattern);board.append(defs,el('rect',{width:1200,height:840,fill:'#fcfdff'}));const t=editing?draftTrack:track;if(t)drawTrack(t);board.append(el('rect',{x:OR,y:OR,width:R.W*S,height:R.H*S,fill:'url(#grid)','pointer-events':'none'}));for(let i=0;i<=R.W;i+=5)board.append(textAt(R.P(i,-.6),String(i),{'text-anchor':'middle','font-size':11}));for(let i=0;i<=R.H;i+=5)board.append(textAt(R.P(-.7,i+.15),String(i),{'text-anchor':'middle','font-size':11}));
if(editing){if(draft.length)board.append(el('polyline',{points:pointStr(draft),fill:'none',stroke:'#3165dd','stroke-width':2,'stroke-dasharray':'5 5'}));draft.forEach((p,i)=>{const q=xy(p);board.append(el('circle',{cx:q.x,cy:q.y,r:5,fill:'#3165dd'}));if(draft.length<25)board.append(textAt(R.P(p.x+.3,p.y-.3),String(i+1),{fill:'#3165dd','font-size':12}));});if(!draft.length)board.append(textAt(R.P(23,15),'在画布上画下你的路线',{'text-anchor':'middle','font-size':24,fill:'#879ab4'}));return;}
if(!state){track.starts.forEach((p,i)=>board.append(actionPoint(p,8,{fill:'#fff',stroke:'#15886e','stroke-width':3},()=>chooseStart(p),`起点 ${i+1} (${p.x},${p.y})`)));return;}
const trail=history.map(s=>s.status==='running'?s.position:s.impact);if(trail.length>1)board.append(el('polyline',{points:pointStr(trail),fill:'none',stroke:'#df5b27','stroke-width':3,'stroke-linejoin':'round'}));trail.slice(0,-1).forEach((p,i)=>{const q=xy(p);board.append(el('circle',{cx:q.x,cy:q.y,r:3,fill:'#df5b27'}));board.append(textAt(R.P(p.x+.25,p.y-.25),String(i),{'font-size':11,fill:'#a76c52'}));});
if(state.status==='running'){const center={x:state.position.x+state.velocity.x,y:state.position.y+state.velocity.y};board.append(line(state.position,center,{stroke:'#8294ae','stroke-width':2,'stroke-dasharray':'7 6'}));board.append(el('rect',{x:xy(center).x-S*1.5,y:xy(center).y-S*1.5,width:S*3,height:S*3,rx:4,fill:'#3165dd05',stroke:'#7a9fe455','stroke-dasharray':'4 5'}));for(let ay=-1;ay<=1;ay++)for(let ax=-1;ax<=1;ax++){const o=R.evaluate(track,state,ax,ay),danger=o.status==='crashed'&&$('warnings').checked,color=danger?'#c7524a':o.status==='finished'?'#8051c9':'#3165dd';const c=actionPoint(o.position,7,{fill:danger?'#fff1ee':'#fff',stroke:color,'stroke-width':2.5},()=>move(ax,ay),`落点 (${o.position.x},${o.position.y})${danger?'，会撞墙':''}`);c.addEventListener('mouseenter',()=>setPreview(ax,ay));c.addEventListener('mouseleave',()=>setPreview(null));c.addEventListener('focus',()=>setPreview(ax,ay));c.addEventListener('blur',()=>setPreview(null));board.append(c);if(danger){const p=xy(o.position);board.append(el('path',{d:`M${p.x-3} ${p.y-3}l6 6m0 -6l-6 6`,stroke:color,'stroke-width':1.5,'pointer-events':'none'}));}}}
const car=state.status==='running'?state.position:state.impact,q=xy(car);board.append(el('circle',{cx:q.x,cy:q.y,r:12,fill:'#df5b2720','pointer-events':'none'}),el('circle',{cx:q.x,cy:q.y,r:6,fill:state.status==='crashed'?'#ba3b35':'#df5b27',stroke:'#fff','stroke-width':2,'pointer-events':'none'}));if(state.status==='crashed')board.append(el('path',{d:`M${q.x-11} ${q.y-11}l22 22m0 -22l-22 22`,stroke:'#ba3b35','stroke-width':3,'pointer-events':'none'}));board.append(el('g',{id:'previewLayer','pointer-events':'none'}));drawPreview();}
function setPreview(ax,ay){preview=ax===null?null:{ax,ay};drawPreview();document.querySelectorAll('#movePad button').forEach(b=>b.classList.toggle('preview',!!preview&&Number(b.dataset.ax)===ax&&Number(b.dataset.ay)===ay));}
function drawPreview(){const layer=$('previewLayer');if(!layer)return;layer.replaceChildren();if(!preview||!state||state.status!=='running')return;const o=R.evaluate(track,state,preview.ax,preview.ay),warn=$('warnings').checked&&o.status==='crashed';layer.append(line(state.position,o.position,{stroke:warn?'#c7524a':'#3165dd','stroke-width':3,'stroke-dasharray':'4 4'}));if(warn){const p=xy(o.impact);layer.append(el('circle',{cx:p.x,cy:p.y,r:10,fill:'#c7524a25',stroke:'#c7524a','stroke-width':2}));}}
function render(){renderBoard();const n=Math.max(0,history.length-1);$('trackTitle').textContent=editing?'画一条自己的路':track.name;$('modeTag').textContent=editing?'赛道编辑':practice?'练习模式':'单人挑战';$('turns').textContent=String(n).padStart(2,'0');$('speed').textContent=state?Math.hypot(state.velocity.x,state.velocity.y).toFixed(1):'0.0';$('velocity').textContent=state?`${state.velocity.x<0?'左':'右'} ${Math.abs(state.velocity.x)} · ${state.velocity.y<0?'上':'下'} ${Math.abs(state.velocity.y)}`:'尚未移动';
let phase='准备发车',title='选择你的起点',desc='点击绿色起跑线上的任意圆点。';if(editing){phase='赛道编辑';title='画好路线，就能出发';desc='按顺序画出中心路线，首尾分别是起点和终点。';}else if(state?.status==='running'){phase='第 '+(n+1)+' 回合';title='这一步，往哪里走？';desc='点击蓝色候选点。虚线延长线的终点，是下一步九宫格的中心。';}else if(state?.status==='crashed'){phase='本次试跑结束';title='撞墙了';desc='试着更早减速入弯。可以重新发车，或撤销一步继续练习。';}else if(state?.status==='finished'){phase=practice?'练习完成':'成功完赛';title=`${n} 回合，到达终点`;desc=practice?'本局为练习，不计入最佳成绩。':'漂亮的路线。再跑一次，试试能不能少用一回合。';}
$('phase').textContent=phase;$('statusTitle').textContent=title;$('statusText').textContent=desc;$('moveCaption').textContent=editing?'画线中':state?.status==='running'?'调整下一步速度':'等待发车';$('undo').disabled=editing||history.length<2;$('restart').disabled=editing;$('warnings').disabled=editing;const best=stored(recordKey());$('record').textContent='个人最佳：'+(Number.isInteger(best)?best+' 回合':'—')+(practice?' · 当前为练习':'');$('editor').hidden=!editing;$('edit').hidden=editing;$('trackSelect').disabled=editing;$('export').disabled=editing;$('import').disabled=editing;board.classList.toggle('editor-active',editing);$('boardNote').textContent=editing?'点击连线 / 按住拖画':'起点 → 终点 · 开放赛道';
document.querySelectorAll('#movePad button').forEach(b=>{const active=false;b.disabled=!active;b.classList.remove('danger','finish','preview');if(active){const o=R.evaluate(track,state,+b.dataset.ax,+b.dataset.ay);if($('warnings').checked&&o.status==='crashed')b.classList.add('danger');if(o.status==='finished')b.classList.add('finish');b.title=`下一步：横向 ${o.velocity.x}，纵向 ${o.velocity.y}`+($('warnings').checked&&o.status==='crashed'?'（会撞墙）':'');}});}
const arrows=['↖','↑','↗','←','○','→','↙','↓','↘'];for(let i=0;i<9;i++){const b=document.createElement('button'),ax=i%3-1,ay=Math.floor(i/3)-1;b.textContent=arrows[i];b.dataset.ax=ax;b.dataset.ay=ay;b.setAttribute('aria-label',ax===0&&ay===0?'保持速度':`速度调整 ${arrows[i]}`);b.onclick=()=>move(ax,ay);b.onmouseenter=()=>setPreview(ax,ay);b.onmouseleave=()=>setPreview(null);b.onfocus=()=>setPreview(ax,ay);b.onblur=()=>setPreview(null);$('movePad').append(b);}
function updateDraft(){draftTrack=null;let msg='先画一段至少 6 格长的路线。';if(draft.length>=2){try{draftTrack=R.makeTrack({name:'手绘赛道',points:draft,width:+$('width').value});msg='路线已就绪，可以开始试跑。';}catch(e){msg=e.message;}}$('editorMessage').textContent=msg;$('applyTrack').disabled=!draftTrack;$('removeNode').disabled=!draft.length;$('widthValue').textContent=$('width').value+' 格';render();}
function startEditor(){editing=true;draft=[];draftTrack=null;preview=null;updateDraft();}
function boardPoint(e){const p=board.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const q=p.matrixTransform(board.getScreenCTM().inverse());return {x:Math.max(3,Math.min(R.W-3,((q.x-OR)/S))),y:Math.max(3,Math.min(R.H-3,((q.y-OR)/S)))};}
function addDraft(p){if(draft.length>=160){toast('路线最多 160 个点，请用较长的线段。');return;}if(draft.length&&Math.hypot(p.x-draft.at(-1).x,p.y-draft.at(-1).y)<1)return;draft.push(p);lastDrag=p;updateDraft();}
board.addEventListener('pointerdown',e=>{if(!editing||e.button!==0)return;drawing=true;board.setPointerCapture(e.pointerId);addDraft(boardPoint(e));});board.addEventListener('pointermove',e=>{if(!editing||!drawing)return;const p=boardPoint(e);if(!lastDrag||Math.hypot(p.x-lastDrag.x,p.y-lastDrag.y)>=3)addDraft(p);});board.addEventListener('pointerup',e=>{drawing=false;lastDrag=null;if(board.hasPointerCapture(e.pointerId))board.releasePointerCapture(e.pointerId);});board.addEventListener('pointercancel',()=>{drawing=false;lastDrag=null;});
function selectCustom(t){track=t;custom={name:t.name,points:t.points,width:t.width};let option=$('customOption');if(!option){option=document.createElement('option');option.id='customOption';option.value='custom';$('trackSelect').append(option);}option.textContent=t.name+' · 自定义';$('trackSelect').value='custom';stored('paper-racer-v2-custom',custom);editing=false;reset();}
$('restart').onclick=reset;$('undo').onclick=undo;$('warnings').onchange=render;$('edit').onclick=startEditor;$('width').oninput=updateDraft;$('clearDraft').onclick=()=>{draft=[];updateDraft();};$('removeNode').onclick=()=>{draft.pop();updateDraft();};$('cancelEdit').onclick=()=>{editing=false;render();};$('applyTrack').onclick=()=>{if(draftTrack)selectCustom(draftTrack);};$('trackSelect').onchange=()=>{track=R.makeTrack($('trackSelect').value==='custom'?custom:R.presets[$('trackSelect').value]);reset();};$('help').onclick=()=>$('helpDialog').showModal();
$('export').onclick=()=>{const data={format:'paper-racer-track',version:1,name:track.name,width:track.width,points:track.points},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=track.name+'-赛道.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('赛道已导出，可用“导入赛道”再次打开。');};$('import').onclick=()=>$('fileInput').click();$('fileInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error('文件太大，请选择本游戏导出的赛道文件。');const data=JSON.parse(await f.text());if(data.format!=='paper-racer-track'||data.version!==1)throw Error('不是支持的纸上赛车赛道文件。');const t=R.makeTrack(data);selectCustom(t);toast('赛道已载入，请选择起点。');}catch(err){toast('导入失败：'+err.message);}e.target.value='';};
document.addEventListener('keydown',e=>{if($('helpDialog').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||e.altKey||e.metaKey)return;if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();if(editing){draft.pop();updateDraft();}else undo();return;}if(e.ctrlKey)return;if(e.key.toLowerCase()==='r'&&!editing){reset();return;}const n=Number(e.code.replace('Numpad',''));if(e.code.startsWith('Numpad')&&n>=1&&n<=9){e.preventDefault();const ax=(n-1)%3-1,ay=1-Math.floor((n-1)/3),d=Math.max(1,Math.hypot(ax,ay));move(ax/d,ay/d);}});
const saved=stored('paper-racer-v2-custom');if(saved){try{const t=R.makeTrack(saved);custom=saved;const option=document.createElement('option');option.id='customOption';option.value='custom';option.textContent=t.name+' · 自定义';$('trackSelect').append(option);}catch{}}
render();
// Optional agent controls, using exactly the same actions as the visible game.
if(document.modelContext?.registerTool){
const lifetime=new AbortController();
const summary=()=>({track:track.name,editing,practice,turns:Math.max(0,history.length-1),state:state?structuredClone(state):null,starts:track.starts,choiceDisk:state?.status==='running'?{center:{x:state.position.x+state.velocity.x,y:state.position.y+state.velocity.y},radius:1}:null});
const tool=(name,description,inputSchema,execute,readOnly=false)=>{try{Promise.resolve(document.modelContext.registerTool({name,description,inputSchema,execute,annotations:{readOnlyHint:readOnly,untrustedContentHint:false}},{signal:lifetime.signal})).catch(()=>{});}catch{}};
tool('read_race','Read current track, race state and nine available moves.',{type:'object',properties:{},additionalProperties:false},summary,true);
tool('start_race','Start or restart a race on a preset or current track; practice mode does not save records.',{type:'object',properties:{track:{type:'string',enum:['current','bay','rookie','snake']},startIndex:{type:'integer',minimum:0},practice:{type:'boolean'}},required:['track','startIndex','practice'],additionalProperties:false},input=>{if(!input||!['current','bay','rookie','snake'].includes(input.track)||!Number.isInteger(input.startIndex)||typeof input.practice!=='boolean')throw Error('Invalid race setup');const next=input.track==='current'?track:R.makeTrack(R.presets[input.track]);if(input.startIndex<0||input.startIndex>=next.starts.length)throw Error('Invalid start index');track=next;editing=false;if(input.track!=='current')$('trackSelect').value=input.track;chooseStart(track.starts[input.startIndex]);practice=input.practice;render();return summary();});
tool('play_race_moves','Execute one or more acceleration choices. Stops on crash or finish and updates the visible board.',{type:'object',properties:{moves:{type:'array',minItems:1,maxItems:100,items:{type:'object',properties:{ax:{type:'number',minimum:-1,maximum:1},ay:{type:'number',minimum:-1,maximum:1}},required:['ax','ay'],additionalProperties:false}}},required:['moves'],additionalProperties:false},input=>{if(!input||!Array.isArray(input.moves)||input.moves.length<1||input.moves.length>100||input.moves.some(m=>!m||!Number.isFinite(m.ax)||!Number.isFinite(m.ay)||Math.hypot(m.ax,m.ay)>1+1e-8))throw Error('Acceleration length must not exceed 1');if(editing||state?.status!=='running')throw Error('Start a race first');let applied=0;for(const m of input.moves){if(state.status!=='running')break;move(m.ax,m.ay);applied++;}return {applied,...summary()};});
tool('create_race_track','Create and select a custom centerline track, like drawing and clicking Start trial. Saves locally when browser storage is available.',{type:'object',properties:{name:{type:'string',maxLength:40},width:{type:'number',minimum:3,maximum:9},points:{type:'array',minItems:2,maxItems:160,items:{type:'object',properties:{x:{type:'number'},y:{type:'number'}},required:['x','y'],additionalProperties:false}}},required:['name','width','points'],additionalProperties:false},input=>{const t=R.makeTrack(input);selectCustom(t);return summary();});
window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});
}



